ice(0, 5) as player}<div class="flex justify-between gap-3 text-xs"><span><strong>#{player.recommendationRank}</strong> {player.name} <span class="text-gray-400">{player.position}</span></span><span class="text-gray-500">{player.recommendationScore}</span></div>{/each}</div></div>{/each}</div>{:else}<p class="mt-2 text-xs text-gray-500">Exact recommendation recording starts with the next draft. This draft can still be reconstructed with the postmortem tool.</p>{/if}</details><details class="mt-5"><summary class="cursor-pointer text-sm font-semibold">Full draft board ({session.picks.length} selections)</summary><div class="mt-3 max-h-96 overflow-auto rounded-lg border bg-white divide-y">{#each session.picks as pick}<div class="grid grid-cols-[3rem_1fr_1fr_auto] gap-3 px-3 py-2 text-xs"><strong>#{pick.pickNumber}</strong><span>{pick.playerName}</span><span class="truncate text-gray-500">{pick.teamName}</span><span>{pick.position ?? '—'}</span></div>{/each}</div></details></div>{/if}</article>{/each}</div>
